const { spawnSync } = require('child_process');
const BIN = '/workspace/dataset/test4_executable';

function run(value) {
  const r = spawnSync(BIN, ['--a', value], { encoding: 'buffer', maxBuffer: 200 * 1024 * 1024 });
  return { out: r.stdout, err: r.stderr, code: r.status };
}

// binary prints result + "\n"
function runStr(value) {
  const r = run(value);
  let o = r.out;
  if (o.length && o[o.length - 1] === 0x0a) o = o.subarray(0, o.length - 1);
  return { outBuf: o, outStr: o.toString('utf8'), err: r.err.toString('utf8'), code: r.code };
}

function hex(s) {
  if (Buffer.isBuffer(s)) return s.toString('hex');
  return Buffer.from(s, 'utf8').toString('hex');
}

function cps(s) {
  return Array.from(s).map(c => 'U+' + c.codePointAt(0).toString(16).toUpperCase().padStart(4, '0')).join(' ');
}

module.exports = { run, runStr, hex, cps, BIN };
